String describe(Shape shape) {
    return switch (shape) {
        case Circle c when c.radius() > 10 -> "big circle";
        case Circle c                      -> "circle " + c.radius();
        case Square(double side)           -> "square " + side;   // record pattern
        case Rectangle r                   -> "rect";
    }; // exhaustive because Shape is sealed — no default needed
}

